    end

    if ~erri
        err = false;
        err2 = true;
        s=sfroot;
        transition = find(s,'-isa','Stateflow.Transition');
        clear s 
        for i = 1:size(transition,1)
            src = string(get(transition(i).Source,'Name'));
            if isempty(src)
                src = "";
            end
            dst = string(get(transition(i).Destination,'Name'));
            if isempty(dst)
                dst = "";
            end
            if src == "ActivatedState" & dst == "InitialState"
